<script lang="ts">
  import {onMount,tick} from 'svelte'
  import {Home,Compass,Users,Bookmark,BookOpen,Search,Settings2,Menu,X,Plus,Sun,Moon,ArrowUpRight,ArrowLeft,Send,Globe,LockKeyhole,ShieldCheck,RefreshCw,LoaderCircle,MessageCircle,ChevronRight,LogOut,Flag,Check,FileText,GitPullRequest,History,Radio,Clock,Link2} from '@lucide/svelte'
  import PostCard from './PostCard.svelte'
  import {request,setCsrf,ApiError,relativeDate,initials,type Actor,type Community,type Post,type Membership,type WikiPage,type Proposal,type Auth,type Capabilities} from './api'
  let path=$state(location.pathname),search=$state(location.search),loading=$state(true),busy=$state(false),message=$state(''),error=$state(''),menu=$state(false)
  let theme=$state<'light'|'dark'>('dark'),auth=$state<Auth>({actor:null,csrf:null,steward:false}),cap=$state<Capabilities|null>(null)
  let communities=$state<Community[]>([]),posts=$state<Post[]>([]),memberships=$state<Membership[]>([]),wiki=$state<WikiPage[]>([]),saved=$state<Post[]>([]),nextCursor=$state<string|null>(null)
  let selectedPost=$state<Post|null>(null),replies=$state<Post[]>([]),selectedPage=$state<WikiPage|null>(null),proposals=$state<Proposal[]>([]),history=$state<{id:string;created:number;perspective:string;language:string}[]>([])
  let tab=$state('discussion'),feedTab=$state('new'),query=$state(''),handle=$state(''),publishingConsent=$state(false),replyText=$state(''),replyParent=$state<string|null>(null),inviteHandle=$state('')
  let modal=$state<null|'compose'|'community'|'wiki'|'proposal'|'manage'|'join'>(null),dialog:HTMLDialogElement,menuDialog:HTMLDialogElement
  let text=$state(''),title=$state(''),description=$state(''),visibility=$state<Community['visibility']>('public'),communityId=$state(''),citations=$state(''),language=$state('id'),perspective=$state(''),modalError=$state('')
  let joinRequests=$state<{actor_id:string;message:string;state:string}[]>([]),reports=$state<{id:string;post_id:string;reason:string;state:string}[]>([])
  let generation=0,notificationTimer:ReturnType<typeof setTimeout>|undefined
  const parts=$derived(path.split('/').filter(Boolean)),community=$derived(communities.find(c=>c.id===parts[1])),isMember=(id:string)=>memberships.some(m=>m.community_id===id)
  const isSteward=(id:string)=>memberships.some(m=>m.community_id===id&&['owner','moderator'].includes(m.role))
  const currentMembership=$derived(community?memberships.find(m=>m.community_id===community.id):undefined)
  const displayPosts=$derived(path==='/saved'?saved:feedTab==='mine'?posts.filter(p=>isMember(p.community_id)):posts)
  const heading=$derived(path==='/'?'Beranda':parts[0]==='explore'?'Jelajah':parts[0]==='communities'?(community?.title??'Komunitas'):parts[0]==='wiki'?'Wiki':parts[0]==='saved'?'Tersimpan':parts[0]==='preferences'?'Pengaturan':parts[0]==='login'?'Masuk':parts[0]==='find'?'Cari':parts[0]==='square'?'Percakapan':parts[0]==='people'?'Profil':'Strata')
  const nav=[{href:'/',label:'Beranda',icon:Home},{href:'/explore',label:'Jelajah',icon:Compass},{href:'/communities',label:'Komunitas',icon:Users},{href:'/wiki',label:'Wiki',icon:BookOpen},{href:'/saved',label:'Tersimpan',icon:Bookmark}]
  function notify(value:string){message=value;clearTimeout(notificationTimer);notificationTimer=setTimeout(()=>message='',6500)}
  function fail(value:unknown){notify(value instanceof Error?value.message:'Permintaan belum dapat diselesaikan.')}
  function navigate(href:string){const u=new URL(href,location.origin);historyPush(u);void load();document.getElementById('commons-main')?.focus();window.scrollTo({top:0,behavior:'instant'})}
  function historyPush(u:URL){window.history.pushState({},'',u);path=u.pathname;search=u.search;menu=false;tab='discussion'}
  function intercept(e:MouseEvent){if(e.button!==0||e.metaKey||e.ctrlKey||e.altKey||e.shiftKey)return;const a=e.target instanceof Element?e.target.closest('a'):null;if(!a||a.target||a.hasAttribute('download'))return;const u=new URL(a.href,location.href);if(u.origin!==location.origin||u.pathname.startsWith('/auth/')||u.pathname.startsWith('/oauth/'))return;if(u.pathname===location.pathname&&u.search===location.search&&u.hash)return;e.preventDefault();navigate(u.pathname+u.search+u.hash)}
  async function load(){
    const mine=++generation;loading=true;error=''
    try{
      const identity=await request<Auth>('/auth/me');if(mine!==generation)return;auth=identity;setCsrf(identity.csrf)
      const filters=new URLSearchParams({roots:'true',limit:'30'})
      if(parts[0]==='communities'&&parts[1])filters.set('community',parts[1])
      if(parts[0]==='find')filters.set('q',new URLSearchParams(search).get('q')??'')
      const [cs,feed,pages,roles,features]=await Promise.all([request<Community[]>('/v1/communities'),request<{items:Post[];nextCursor:string|null}>('/v1/feed/page?'+filters),request<WikiPage[]>('/v1/wiki'),identity.actor?request<Membership[]>('/v1/memberships'):Promise.resolve([]),request<Capabilities>('/v1/capabilities')])
      if(mine!==generation)return;communities=cs;posts=feed.items;wiki=pages;memberships=roles;cap=features;nextCursor=feed.nextCursor;selectedPost=null;replies=[];selectedPage=null;proposals=[];history=[]
      if(path==='/saved'&&identity.actor){const rows=await request<Post[]>('/v1/bookmarks');if(mine===generation)saved=rows}else saved=[]
      if(parts[0]==='square'&&parts[1]){
        const p=await request<Post>('/v1/posts/'+parts[1]);const thread=await request<{items:Post[]}>('/v1/posts/'+p.id+'/replies');if(mine!==generation)return;selectedPost=p;replies=thread.items.reverse()
      }
      if(parts[0]==='wiki'&&parts[1]){
        const p=await request<WikiPage>('/v1/wiki/'+parts[1]);const h=await request<typeof history>('/v1/wiki/'+p.id+'/history');if(mine!==generation)return;selectedPage=p;history=h
        if(identity.actor&&roles.some(m=>m.community_id===p.community_id)){const drafts=await request<Proposal[]>('/v1/wiki/'+p.id+'/proposals');if(mine===generation)proposals=drafts}
      }
    }catch(e){if(mine===generation){error=e instanceof Error?e.message:'Belum dapat memuat halaman.';if(e instanceof ApiError&&e.status===401){auth={actor:null,csrf:null,steward:false};setCsrf(null);communities=[];posts=[];memberships=[];saved=[]}}}finally{if(mine===generation)loading=false}
  }
  async function mutate(action:()=>Promise<void>){if(busy)return;busy=true;try{await action()}catch(e){fail(e)}finally{busy=false}}
  function open(kind:typeof modal,id=''){if(!auth.actor){navigate('/login');return}modal=kind;communityId=id||memberships[0]?.community_id||communities[0]?.id||'';text='';title='';description='';citations='';perspective='';modalError='';visibility='public';if(kind==='manage')void manage(id)}
  async function manage(id:string){try{[joinRequests,reports]=await Promise.all([request<typeof joinRequests>(`/v1/communities/${id}/requests`),request<typeof reports>(`/v1/communities/${id}/reports`)])}catch(e){modalError=e instanceof Error?e.message:'Belum dapat memuat antrean.'}}
  async function submit(){if(busy)return;busy=true;modalError='';try{
    if(modal==='compose'){const p=await request<Post>('/v1/posts',{communityId,text});modal=null;navigate('/square/'+p.id)}
    else if(modal==='community'){const c=await request<Community>('/v1/communities',{title,description,visibility,admission:visibility==='public'?'approval':'invite'});modal=null;navigate('/communities/'+c.id)}
    else if(modal==='join'){await request(`/v1/communities/${communityId}/requests`,{message:text});modal=null;notify('Permintaan bergabung dikirim.')}
    else if(modal==='wiki'){const p=await request<WikiPage>(`/v1/communities/${communityId}/wiki`,{title});modal=null;navigate('/wiki/'+p.id)}
    else if(modal==='proposal'&&selectedPage){await request(`/v1/wiki/${selectedPage.id}/proposals`,{baseRevision:selectedPage.revision_id,text,citations:citations.split('\n').map(x=>x.trim()).filter(Boolean),language,perspective});modal=null;await load();notify('Usulan dikirim untuk ditinjau.')}
  }catch(e){modalError=e instanceof Error?e.message:'Status belum pasti. Muat ulang sebelum mencoba lagi.'}finally{busy=false}}
  async function login(){await mutate(async()=>{const result=await request<{authorizationUrl:string}>('/auth/start',{handle:handle.trim(),publishing:publishingConsent});location.assign(result.authorizationUrl)})}
  async function logout(){await mutate(async()=>{generation++;posts=[];saved=[];communities=[];memberships=[];selectedPage=null;proposals=[];replies=[];selectedPost=null;await request('/auth/logout',{});auth={actor:null,csrf:null,steward:false};setCsrf(null);navigate('/')})}
  async function more(){if(!nextCursor||busy)return;await mutate(async()=>{const q=new URLSearchParams({roots:'true',limit:'30',cursor:nextCursor!});if(community)q.set('community',community.id);const page=await request<{items:Post[];nextCursor:string|null}>('/v1/feed/page?'+q);posts=[...posts,...page.items];nextCursor=page.nextCursor})}
  async function reply(){if(!selectedPost||!replyText.trim())return;await mutate(async()=>{await request('/v1/posts',{communityId:selectedPost!.community_id,text:replyText,parentId:replyParent??selectedPost!.id});replyText='';replyParent=null;await load()})}
  async function decide(p:Proposal,accept:boolean){await mutate(async()=>{await request(`/v1/wiki-proposals/${p.id}/decide`,{digest:p.digest,accept});await load();notify(accept?'Revisi diterima.':'Usulan ditolak.')})}
  $effect(()=>{document.documentElement.dataset.commonsTheme=theme;document.documentElement.style.colorScheme=theme;try{localStorage.setItem('strata.ui.theme',theme)}catch{}})
  $effect(()=>{if(!menuDialog)return;if(menu&&!menuDialog.open)menuDialog.showModal();else if(!menu&&menuDialog.open)menuDialog.close()})
  $effect(()=>{if(!dialog)return;if(modal&&!dialog.open)dialog.showModal();else if(!modal&&dialog.open)dialog.close()})
  onMount(()=>{try{const value=localStorage.getItem('strata.ui.theme');if(value==='light'||value==='dark')theme=value}catch{}void load();return()=>clearTimeout(notificationTimer)})
</script>

<svelte:head><title>{heading} · ETNOS</title></svelte:head>
<svelte:window onclick={intercept} onpopstate={()=>{path=location.pathname;search=location.search;void load()}}/>
<div class="cx-root">
  <a class="cx-skip" href="#commons-main">Lewati navigasi</a>
  {#snippet navigation()}
    <a href="/" class="cx-brand">etnos<span>.</span></a>
    <nav class="cx-nav" aria-label="Navigasi utama">{#each nav as item}<a href={item.href} class:active={item.href==='/'?path==='/':path.startsWith(item.href)} aria-current={(item.href==='/'?path==='/':path.startsWith(item.href))?'page':undefined}><item.icon size={20} strokeWidth={1.7}/><span>{item.label}</span></a>{/each}</nav>
    <button class="cx-nav-create" onclick={()=>open('compose')}><Plus size={19}/>Posting</button>
    <div class="cx-sidebar-bottom"><a href="/preferences" class="cx-nav-more"><Settings2 size={19}/>Pengaturan</a>{#if auth.actor}<a href={'/people/'+auth.actor.id} class="cx-current-user"><span class="cx-avatar sage small">{initials(auth.actor.name)}</span><span><strong>{auth.actor.name}</strong><small>Akun AT terhubung</small></span></a>{:else}<a href="/login" class="cx-button primary">Masuk</a>{/if}<span class="cx-workspace-label"><span></span>Papua · pratinjau</span></div>
  {/snippet}
  <aside class="cx-sidebar">{@render navigation()}</aside>
  <div class="cx-workspace">
    <header class="cx-topbar"><a href="/" class="cx-mobile-brand">etnos<span>.</span></a><div class="cx-location"><span>Papua</span><span>/</span><strong>{heading}</strong></div><form class="cx-global-search" onsubmit={e=>{e.preventDefault();navigate('/find?q='+encodeURIComponent(query))}}><Search size={17}/><input bind:value={query} placeholder="Cari percakapan" aria-label="Cari percakapan" style="background:none;border:0;outline:none;min-width:0;width:100%;color:inherit"/></form><div class="cx-topbar-actions"><button class="cx-icon-button" aria-label={theme==='dark'?'Tema terang':'Tema gelap'} onclick={()=>theme=theme==='dark'?'light':'dark'}>{#if theme==='dark'}<Sun size={18}/>{:else}<Moon size={18}/>{/if}</button><button class="cx-icon-button cx-mobile-menu" aria-label="Menu" onclick={()=>menu=true}><Menu size={20}/></button></div></header>
    <div class="cx-content-grid">
      <main id="commons-main" class="cx-main" tabindex="-1">
        {#if loading}<div class="strata-card strata-inline strata-pending" role="status"><LoaderCircle size={18}/>Memuat…</div>{/if}
        {#if error}<div class="strata-card"><p class="strata-alert" role="alert">{error}</p><button class="cx-button small" style="margin-top:14px" onclick={()=>load()}><RefreshCw size={14}/>Coba lagi</button></div>
        {:else if path==='/login'}
          <div class="cx-page-head"><h1>Masuk</h1><span class="strata-pill">AT Protocol</span></div><section class="strata-narrow"><form class="cx-form" onsubmit={e=>{e.preventDefault();login()}}><label>Handle akun<input bind:value={handle} placeholder="giyaibo.bsky.social" autocomplete="username" autocapitalize="none" spellcheck="false" required/></label><p class="cx-hint">Kata sandi tetap di penyedia akunmu. Keanggotaan komunitas memerlukan persetujuan tersendiri.</p>{#if cap?.publication.liveAT}<label class="strata-inline"><input type="checkbox" bind:checked={publishingConsent}/>Hubungkan penerbitan Strata ke AT</label>{/if}{#if new URLSearchParams(search).has('error')}<p class="cx-form-error" role="alert">Sesi masuk belum selesai atau sudah berakhir. Coba lagi dari halaman ini.</p>{/if}<button class="cx-button primary" disabled={busy}>{#if busy}<LoaderCircle size={16}/>{/if}Lanjutkan<ArrowUpRight size={15}/></button></form><p class="cx-hint" style="margin-top:25px">Pratinjau ini menerima akun yang diundang. Belum punya akun AT? <a class="cx-text-link" href="https://bsky.app" target="_blank" rel="noreferrer">Buat akun di penyedia AT ↗</a></p></section>
        {:else if path==='/preferences'}
          <div class="cx-page-head"><h1>Pengaturan</h1></div><section class="strata-card strata-preferences"><label class="cx-form">Tampilan<select bind:value={theme}><option value="dark">Gelap</option><option value="light">Terang</option></select></label>{#if auth.actor}<div><strong>{auth.actor.name}</strong><p class="cx-hint" style="overflow-wrap:anywhere">{auth.actor.did}</p></div><p class="cx-hint">Akun tetap berada di PDS asal. Tidak ada migrasi akun.</p><button class="cx-button" disabled={busy} onclick={logout}><LogOut size={16}/>Keluar dari perangkat ini</button>{#if auth.steward}<form class="cx-form" onsubmit={e=>{e.preventDefault();mutate(async()=>{await request('/auth/invite',{handle:inviteHandle});inviteHandle='';notify('Akun dapat masuk. Keanggotaan komunitas tetap terpisah.')})}}><label>Undang akun ke Strata<input bind:value={inviteHandle} placeholder="nama.domain" required/></label><button class="cx-button small" disabled={busy}>Undang akun</button></form>{/if}{:else}<a href="/login" class="cx-button primary">Masuk</a>{/if}</section>
        {:else if parts[0]==='wiki'}
          <div class="cx-page-head"><h1>{selectedPage?.title??'Wiki'}</h1>{#if !selectedPage&&memberships.some(m=>m.role!=='member')}<button class="cx-button small" onclick={()=>open('wiki')}><Plus size={14}/>Halaman</button>{/if}</div>
          {#if selectedPage}<section class="strata-card"><a href="/wiki" class="cx-back"><ArrowLeft size={14}/>Wiki</a>{#if selectedPage.revision}<p class="strata-caption"><FileText size={14}/>{selectedPage.revision.language} · {selectedPage.revision.perspective}</p><div class="cx-document strata-body" style="margin:20px 0">{selectedPage.revision.text}</div>{#each selectedPage.revision.citations as url}<a class="strata-source" href={url} target="_blank" rel="noreferrer">{url}<ArrowUpRight size={12}/></a>{/each}{:else}<p class="cx-muted">Belum ada revisi yang diterima.</p>{/if}{#if isMember(selectedPage.community_id)}<button class="cx-button small" style="margin-top:18px" onclick={()=>{open('proposal');text=selectedPage?.revision?.text??'';language=selectedPage?.revision?.language??'id';perspective=selectedPage?.revision?.perspective??'';citations=selectedPage?.revision?.citations.join('\n')??''}}><GitPullRequest size={14}/>Usulkan perubahan</button>{/if}</section>
            {#if proposals.length}<section class="strata-card"><h2 style="font-size:16px">Usulan</h2>{#each proposals as p}<article class="strata-review"><span class="strata-pill">{p.state==='pending'?'Menunggu tinjauan':p.state==='accepted'?'Diterima':'Ditolak'}</span><p class="strata-caption" style="margin-top:12px">{p.language} · {p.perspective}</p><p class="strata-body">{p.text}</p>{#each p.citations as url}<a class="strata-source" href={url} target="_blank" rel="noreferrer">{url}</a>{/each}{#if p.state==='pending'&&isSteward(selectedPage.community_id)}<div class="cx-actions" style="margin-top:16px"><button class="cx-button primary small" disabled={busy} onclick={()=>decide(p,true)}>Terima revisi</button><button class="cx-button small" disabled={busy} onclick={()=>decide(p,false)}>Tolak</button></div>{/if}</article>{/each}</section>{/if}
            {#if history.length}<section class="strata-card"><h2 class="strata-inline" style="font-size:16px"><History size={16}/>Riwayat</h2>{#each history as rev}<div class="cx-list-row"><FileText size={16}/><div><strong>{rev.perspective}</strong><small>{rev.language} · {relativeDate(rev.created)}</small></div></div>{/each}</section>{/if}
          {:else if wiki.length}<section>{#each wiki as p}<a href={'/wiki/'+p.id} class="cx-list-row strata-card"><span class="cx-object-icon"><BookOpen size={20}/></span><div><h3>{p.title}</h3><small>{communities.find(c=>c.id===p.community_id)?.title} · {p.revision_id?'Ada revisi diterima':'Belum ada revisi'}</small></div><ChevronRight size={16}/></a>{/each}</section>{:else}<div class="strata-nodata"><div class="strata-empty-graphic"><BookOpen size={27}/></div><h2>Pengetahuan yang bisa ditinjau bersama</h2><p>Halaman, sumber dan revisi yang diterima akan muncul di sini.</p><a class="cx-button" href="/communities">Lihat komunitas</a></div>{/if}
        {:else if parts[0]==='communities'&&parts[1]}
          {#if community}<div class="cx-detail-head"><div class="cx-between"><span class="cx-avatar sage">{initials(community.title)}</span>{#if currentMembership}<span class="strata-pill">{currentMembership.role==='member'?'Anggota':currentMembership.role==='owner'?'Pemilik':'Moderator'}</span>{:else if community.admission==='open'}<button class="cx-button small" disabled={busy} onclick={()=>mutate(async()=>{await request(`/v1/communities/${community.id}/join`,{});await load()})}>Gabung</button>{:else if community.admission==='approval'}<button class="cx-button small" onclick={()=>open('join',community.id)}>Minta bergabung</button>{:else}<span class="strata-pill">Dengan undangan</span>{/if}</div><h1>{community.title}</h1><p>{community.description}</p><div class="strata-caption">{#if community.visibility==='public'}<Globe size={13}/>Publik{:else}<LockKeyhole size={13}/>Khusus anggota{/if}<span>·</span>{community.publication==='atproto'?'Penerbitan AT tersedia':'Percakapan di Strata'}</div><div class="cx-actions" style="margin-top:18px">{#if currentMembership}<button class="cx-button primary small" onclick={()=>open('compose',community.id)}><Plus size={14}/>Posting</button>{/if}{#if isSteward(community.id)}<button class="cx-button small" onclick={()=>open('manage',community.id)}><ShieldCheck size={14}/>Kelola</button>{/if}</div></div><div class="strata-tabs"><button class:active={tab==='discussion'} onclick={()=>tab='discussion'}>Diskusi</button><button class:active={tab==='wiki'} onclick={()=>tab='wiki'}>Wiki</button><button class:active={tab==='about'} onclick={()=>tab='about'}>Tentang</button></div>
            {#if tab==='about'}<section class="strata-card"><p class="strata-body">{community.description}</p><p class="cx-hint">{community.visibility==='public'?'Isi dapat dibaca publik.':'Isi hanya tersedia bagi anggota saat ini.'} {community.admission==='approval'?'Permintaan bergabung ditinjau pengelola.':community.admission==='invite'?'Keanggotaan melalui undangan.':'Keanggotaan terbuka.'}</p></section>{:else if tab==='wiki'}<section class="strata-card">{#each wiki.filter(p=>p.community_id===community.id) as p}<a href={'/wiki/'+p.id} class="cx-list-row"><BookOpen size={18}/>{p.title}<ChevronRight size={15}/></a>{/each}{#if isSteward(community.id)&&community.visibility==='public'}<button class="cx-button small" onclick={()=>open('wiki',community.id)}><Plus size={14}/>Halaman baru</button>{/if}</section>{:else}{#each posts as p}<PostCard post={p} {community} loggedIn={!!auth.actor} canVote={!!currentMembership} onError={notify}/>{/each}{#if !posts.length&&!loading}<div class="strata-nodata"><MessageCircle size={26}/><h2>Belum ada percakapan</h2><p>{currentMembership?'Mulai percakapan pertama.':'Gabung komunitas untuk ikut berbicara.'}</p></div>{/if}{/if}
          {:else if !loading}<div class="strata-nodata"><LockKeyhole size={26}/><h2>Komunitas tidak tersedia</h2><p>Komunitas mungkin tidak ada atau memerlukan akses.</p><a href="/communities" class="cx-button">Komunitas</a></div>{/if}
        {:else if path==='/communities'||path==='/explore'}
          <div class="cx-page-head"><h1>{path==='/explore'?'Jelajah':'Komunitas'}</h1>{#if auth.actor}<button class="cx-button small" onclick={()=>open('community')}><Plus size={14}/>Komunitas</button>{/if}</div><div class="strata-mosaic">{#each communities as c,i}<a href={'/communities/'+c.id} class="strata-tile"><div class="cx-between"><span class="cx-avatar sage small">{initials(c.title)}</span><ArrowUpRight size={18}/></div><div><h2>{c.title}</h2><p>{c.description}</p><span class="strata-small">{c.visibility==='public'?'Publik':'Khusus anggota'}{isMember(c.id)?' · Bergabung':''}</span></div></a>{/each}</div>{#if !communities.length&&!loading}<div class="strata-nodata"><div class="strata-empty-graphic"><Users size={27}/></div><h2>Ruang untuk komunitasmu</h2><p>Komunitas pertama dibuat setelah steward menyelesaikan proses masuk.</p>{#if !auth.actor}<a href="/login" class="cx-button primary">Masuk</a>{/if}</div>{/if}
        {:else if parts[0]==='square'}
          <a href="/" class="cx-back"><ArrowLeft size={14}/>Beranda</a>{#if selectedPost}<PostCard post={selectedPost} community={communities.find(c=>c.id===selectedPost!.community_id)} loggedIn={!!auth.actor} canVote={isMember(selectedPost.community_id)} detail onError={notify}/><section id="replies" class="strata-card"><h2 style="font-size:16px;margin-bottom:18px">Diskusi <span class="cx-muted">{selectedPost.replies}</span></h2>{#if auth.actor&&isMember(selectedPost.community_id)}<form class="cx-form" onsubmit={e=>{e.preventDefault();reply()}}>{#if replyParent}<button class="cx-text-link" type="button" onclick={()=>replyParent=null}>Membalas · batal</button>{/if}<textarea bind:value={replyText} required maxlength="6000" placeholder="Tulis balasan…" aria-label="Tulis balasan"></textarea><div class="cx-actions"><button class="cx-button primary small" disabled={busy||!replyText.trim()}>Balas<Send size={13}/></button></div></form>{:else}<a href={auth.actor?'/communities/'+selectedPost.community_id:'/login'} class="cx-text-link">{auth.actor?'Gabung komunitas untuk membalas':'Masuk untuk membalas'}</a>{/if}<div class="strata-replies">{#each replies as r}<article class="strata-reply"><div class="cx-post-meta"><a class="cx-author" href={'/people/'+r.author.id}>{r.author.name}</a><span class="cx-meta-secondary">{relativeDate(r.created)}</span></div><p class="strata-body">{r.text}</p>{#if auth.actor&&isMember(r.community_id)}<button class="cx-text-link" onclick={()=>{replyParent=r.id;document.querySelector<HTMLTextAreaElement>('#replies textarea')?.focus()}}>Balas</button>{/if}</article>{/each}</div></section>{:else if !loading}<div class="strata-nodata"><h2>Posting tidak tersedia</h2></div>{/if}
        {:else if parts[0]==='people'}
          {@const actor=auth.actor?.id===parts[1]?auth.actor:posts.find(p=>p.author.id===parts[1])?.author}{#if actor}<div class="cx-detail-head"><span class="cx-avatar sage">{initials(actor.name)}</span><h1>{actor.name}</h1><p class="cx-hint" style="overflow-wrap:anywhere">{actor.did}</p>{#if actor.kind==='agent'}<span class="strata-pill">AI</span>{/if}</div>{#each posts.filter(p=>p.author.id===actor.id) as p}<PostCard post={p} community={communities.find(c=>c.id===p.community_id)} loggedIn={!!auth.actor} canVote={isMember(p.community_id)} onError={notify}/>{/each}{:else if !loading}<div class="strata-nodata"><h2>Profil tidak tersedia</h2><p>Identitas anggota privat tidak ditampilkan dalam direktori publik.</p></div>{/if}
        {:else if path==='/'||path==='/saved'||path==='/find'}
          {#if path==='/saved'}<div class="cx-page-head"><h1>Tersimpan</h1><Bookmark size={18}/></div>{:else if path==='/find'}<div class="cx-page-head"><h1>Hasil pencarian</h1></div>{:else}<div class="strata-tabs"><button class:active={feedTab==='new'} onclick={()=>feedTab='new'}>Terbaru</button><button class:active={feedTab==='mine'} onclick={()=>feedTab='mine'}>Komunitasku</button><button class="cx-icon-button" aria-label="Muat ulang" style="margin-left:auto" onclick={()=>load()}><RefreshCw size={15}/></button></div><div class="cx-composer-bar"><span class="cx-avatar sage">{auth.actor?initials(auth.actor.name):'+'}</span><button onclick={()=>open('compose')}>Apa yang terjadi?</button><button class="cx-button primary" onclick={()=>open('compose')}>Posting</button></div>{/if}
          {#each displayPosts as p}<PostCard post={p} community={communities.find(c=>c.id===p.community_id)} loggedIn={!!auth.actor} canVote={isMember(p.community_id)} onError={notify} onSaved={()=>{if(path==='/saved')saved=saved.filter(x=>x.bookmarked)}}/>{/each}
          {#if !displayPosts.length&&!loading}<div class="strata-nodata"><div class="strata-empty-graphic">{#if path==='/saved'}<Bookmark size={27}/>{:else}<MessageCircle size={27}/>{/if}</div><h2>{path==='/saved'?'Simpan untuk nanti':path==='/find'?'Belum ada hasil':'Percakapan dimulai di sini'}</h2><p>{path==='/saved'?'Posting yang kamu simpan tersedia selama kamu memiliki akses.':'Temukan komunitas, ajukan pertanyaan dan bagikan sesuatu yang berguna.'}</p><a href={path==='/saved'&&!auth.actor?'/login':'/communities'} class="cx-button">{path==='/saved'&&!auth.actor?'Masuk':'Lihat komunitas'}</a></div>{/if}
          {#if nextCursor&&path==='/'}<div class="strata-card"><button class="cx-button" disabled={busy} onclick={more}>Muat posting lain</button></div>{/if}
        {:else}<div class="strata-nodata"><h2>Halaman tidak tersedia</h2><a href="/" class="cx-button">Beranda</a></div>{/if}
      </main>
      <aside class="cx-context" aria-label="Konteks terkait"><div class="cx-context-block"><div class="cx-section-head"><h2>Komunitas</h2><a href="/communities" aria-label="Semua komunitas"><ArrowUpRight size={16}/></a></div>{#each communities.slice(0,4) as c}<a href={'/communities/'+c.id} class="cx-community-mini"><span class="cx-avatar sage small">{initials(c.title)}</span><span><strong>{c.title}</strong><small>{c.visibility==='public'?'Publik':'Khusus anggota'}</small></span></a>{/each}{#if !communities.length}<p class="cx-hint">Ruang komunitas akan muncul di sini.</p>{/if}</div><a href="/wiki" class="cx-context-spotlight" style="background:linear-gradient(135deg,#27382e,#171725);padding:22px;min-height:180px;display:flex;align-items:end"><div><BookOpen size={26}/><h3 style="margin-top:22px">Pengetahuan bersama</h3><span>Wiki & revisi<ArrowUpRight size={14}/></span></div></a><div class="cx-context-block"><h2 style="font-size:15px">Satu akun, banyak ruang</h2><p class="cx-hint" style="margin-top:12px">Keanggotaan dan izin tetap mengikuti setiap komunitas.</p><a class="cx-text-link" href="/preferences">Akun & pengaturan<ChevronRight size={13}/></a></div><div class="cx-rail-footer"><a href="https://github.com/yohn-maistre/honai-metro" target="_blank" rel="noreferrer">Honai</a><a href="https://github.com/yohn-maistre/strata" target="_blank" rel="noreferrer">Strata</a><span>Papua · pratinjau terhubung</span></div></aside>
    </div>
  </div>
  <nav class="cx-mobile-dock" aria-label="Navigasi seluler"><a href="/" class:active={path==='/'} aria-label="Beranda"><Home size={22}/></a><a href="/communities" class:active={path.startsWith('/communities')} aria-label="Komunitas"><Users size={22}/></a><button class="cx-dock-compose" aria-label="Posting baru" onclick={()=>open('compose')}><Plus size={23}/></button><a href="/wiki" class:active={path.startsWith('/wiki')} aria-label="Wiki"><BookOpen size={22}/></a><button aria-label="Semua ruang" onclick={()=>menu=true}><Menu size={22}/></button></nav>
  <dialog bind:this={menuDialog} class="strata-menu-dialog" onclose={()=>menu=false} oncancel={()=>menu=false} aria-label="Navigasi"><aside class="strata-menu" aria-label="Menu"><button class="cx-icon-button" style="margin-left:auto;display:block" aria-label="Tutup menu" onclick={()=>menu=false}><X size={20}/></button>{@render navigation()}</aside></dialog>
  {#if message}<div class="cx-toast" role="status"><span>{message}</span><button class="cx-icon-button" aria-label="Tutup notifikasi" onclick={()=>message=''}><X size={16}/></button></div>{/if}
</div>

<dialog bind:this={dialog} class="cx-dialog" onclose={()=>modal=null} oncancel={()=>modal=null} aria-labelledby="dialog-title"><div class="cx-between"><h2 id="dialog-title">{modal==='compose'?'Posting baru':modal==='community'?'Komunitas baru':modal==='wiki'?'Halaman Wiki':modal==='proposal'?'Usulkan perubahan':modal==='join'?'Minta bergabung':'Kelola komunitas'}</h2><button class="cx-icon-button" aria-label="Tutup" onclick={()=>modal=null}><X size={19}/></button></div>
  {#if modal==='manage'}<div class="strata-stack" style="margin-top:20px"><h3 style="font-size:15px">Permintaan bergabung</h3>{#each joinRequests.filter(r=>r.state==='pending') as r}<article class="strata-review"><p>{r.message}</p><div class="cx-actions"><button class="cx-button small" disabled={busy} onclick={()=>mutate(async()=>{await request(`/v1/communities/${communityId}/decide`,{actorId:r.actor_id,approve:true});await manage(communityId)})}>Terima</button><button class="cx-button small" disabled={busy} onclick={()=>mutate(async()=>{await request(`/v1/communities/${communityId}/decide`,{actorId:r.actor_id,approve:false});await manage(communityId)})}>Tolak</button></div></article>{/each}{#if !joinRequests.some(r=>r.state==='pending')}<p class="cx-hint">Tidak ada permintaan yang menunggu.</p>{/if}<h3 style="font-size:15px">Laporan</h3>{#each reports.filter(r=>r.state==='open') as r}<article class="strata-review"><a href={'/square/'+r.post_id} class="cx-text-link" onclick={()=>modal=null}>Lihat posting<ArrowUpRight size={13}/></a><p>{r.reason}</p><button class="cx-button small" disabled={busy} onclick={()=>mutate(async()=>{await request(`/v1/reports/${r.id}/decide`,{state:'resolved',decision:'Ditinjau pengelola melalui Strata'});await manage(communityId)})}>Tandai ditinjau</button></article>{/each}{#if !reports.some(r=>r.state==='open')}<p class="cx-hint">Tidak ada laporan yang menunggu.</p>{/if}</div>
  {:else}<form class="cx-form" style="margin-top:22px" onsubmit={e=>{e.preventDefault();submit()}}>
    {#if modal==='compose'||modal==='wiki'}<label>Komunitas<select bind:value={communityId} required>{#each communities.filter(c=>modal==='wiki'?isSteward(c.id)&&c.visibility==='public':isMember(c.id)) as c}<option value={c.id}>{c.title}{c.visibility==='public'?' · Publik':' · Anggota'}</option>{/each}</select></label>{/if}
    {#if modal==='community'||modal==='wiki'}<label>Nama<input bind:value={title} maxlength="160" required/></label>{/if}
    {#if modal==='community'}<label>Tentang komunitas<textarea bind:value={description} maxlength="2000" required></textarea></label><label>Siapa yang dapat membaca?<select bind:value={visibility}><option value="public">Publik · bergabung dengan persetujuan</option><option value="listed-private">Anggota · nama komunitas terlihat publik</option><option value="hidden-private">Anggota · komunitas disembunyikan</option></select></label>{/if}
    {#if modal==='compose'||modal==='join'||modal==='proposal'}<label>{modal==='join'?'Pesan untuk pengelola':modal==='proposal'?'Isi revisi':'Posting'}<textarea bind:value={text} maxlength={modal==='proposal'?50000:modal==='join'?500:6000} required rows={modal==='proposal'?10:5} placeholder={modal==='compose'?'Apa yang terjadi?':''}></textarea></label>{/if}
    {#if modal==='proposal'}<label>Sumber publik<textarea bind:value={citations} placeholder="Satu URL https per baris" rows="3"></textarea></label><label>Bahasa<input bind:value={language} maxlength="40" required/></label><label>Perspektif / atribusi<input bind:value={perspective} maxlength="300" required/></label><p class="cx-hint">Usulan hanya terlihat oleh penulis dan pengelola. Revisi diterbitkan setelah tinjauan manusia.</p>{/if}
    {#if modal==='compose'}{@const destination=communities.find(c=>c.id===communityId)}<p class="strata-caption">{#if destination?.visibility==='public'}<Globe size={13}/>Publik{#if destination.publication==='atproto'} · Akan masuk antrean AT{:else} · Di Strata{/if}{:else}<LockKeyhole size={13}/>Hanya anggota komunitas{/if}</p>{/if}
    {#if modalError}<p class="cx-form-error" role="alert">{modalError}</p>{/if}<button class="cx-button primary" disabled={busy||((modal==='compose'||modal==='wiki')&&!communityId)}>{#if busy}<LoaderCircle size={15}/>{/if}{modal==='compose'?'Posting':modal==='join'?'Kirim permintaan':modal==='proposal'?'Ajukan untuk tinjauan':'Buat'}<Send size={14}/></button>
  </form>{/if}
</dialog>

<style>.strata-menu-dialog{position:fixed;inset:0 auto 0 0;width:min(300px,85vw);max-width:none;max-height:none;height:100dvh;margin:0;padding:0;border:0;background:var(--cx-panel);color:var(--cx-ink)}.strata-menu-dialog::backdrop{background:rgb(0 0 0/.6)}.strata-menu{width:min(300px,85vw);height:100dvh;overflow:auto;background:var(--cx-panel);padding:20px;display:flex;flex-direction:column;position:relative;z-index:1}.strata-menu :global(.cx-sidebar-bottom){position:static;margin-top:28px}.strata-menu :global(.cx-brand){margin-top:0}@media(min-width:1000px){.strata-menu-dialog{display:none}}</style>
